  const lines = [];
  lines.push(`# Build spec: ${input.title}`, "");
  lines.push("> Generated by Claude Companion for handoff to Claude Code.", "");
  lines.push("## Tasks", "");
  for (const t of input.tasks) lines.push(`- [${t.done ? "x" : " "}] ${t.title}`);
